// Placed after Wait Until Post Time

function log(step, message, data) {
  const suffix =
    data === undefined ? "" : ` ${JSON.stringify(data, null, 2)}`;
  console.log(`[content-approved] ${step} | ${message}${suffix}`);
}

const item = $input.first().json;
const now = new Date();
const scheduledAt = item.scheduledAt ? new Date(item.scheduledAt) : null;
const isDueNow = scheduledAt ? scheduledAt.getTime() <= now.getTime() : null;

log("Wait Until Post Time", "wait finished — resuming workflow", {
  contentId: item.contentId,
  contentCode: item.contentCode ?? item.contentId,
  scheduledAt: item.scheduledAt,
  resumeAt: item.resumeAt,
  checkedAt: item.checkedAt,
  now: now.toISOString(),
  isDueNow,
  msUntilDue: scheduledAt ? scheduledAt.getTime() - now.getTime() : null,
});

return [{ json: item }];

// n8n Code node — Run Once for All Items

function log(step, message, data) {
  const suffix =
    data === undefined ? "" : ` ${JSON.stringify(data, null, 2)}`;
  console.log(`[content-approved] ${step} | ${message}${suffix}`);
}

const legacyBufferChannels = {
  instagram: $env.BUFFER_IG_CHANNEL_ID,
  tiktok: $env.BUFFER_TIKTOK_CHANNEL_ID,
  facebook: $env.BUFFER_FB_CHANNEL_ID,
  youtube: $env.BUFFER_YOUTUBE_CHANNEL_ID,
};

const appUrl = ($env.APP_PUBLIC_URL || "http://localhost:3000").replace(/\/$/, "");

function toPublicUrl(url) {
  if (!url) return null;
  if (url.startsWith("http://") || url.startsWith("https://")) return url;
  return `${appUrl}${url.startsWith("/") ? url : `/${url}`}`;
}

function resolveTargets(content) {
  if (Array.isArray(content.bufferTargets) && content.bufferTargets.length > 0) {
    return content.bufferTargets;
  }

  return (content.platforms || [])
    .map((platform) => ({
      platform,
      bufferChannelId: legacyBufferChannels[platform],
    }))
    .filter((target) => Boolean(target.bufferChannelId));
}

const results = [];

for (const item of $input.all()) {
  const content = item.json;

  log("2/5 Prepare Buffer Posts", "start", {
    contentId: content.contentId,
    id: content.id,
    channel: content.channel,
    isDue: content.isDue,
    checkedAt: content.checkedAt,
  });

  const captionParts = [content.name, content.details];
  if (content.tags?.length) {
    captionParts.push(
      content.tags.map((tag) => `#${String(tag).replace(/^#/, "")}`).join(" ")
    );
  }
  const text = captionParts.filter(Boolean).join("\n\n");

  const mediaUrl =
    toPublicUrl(content.mediaUrl) ||
    (content.attachments || []).map(toPublicUrl).find(Boolean);

  if (!mediaUrl) {
    log("2/5 Prepare Buffer Posts", "ERROR no media URL", {
      contentId: content.contentId,
      attachments: content.attachments,
    });
    throw new Error(
      `Content ${content.id} (${content.contentId}) has no media URL`
    );
  }

  const videoExt = /\.(mp4|mov|webm|m4v)$/i;
  const assetKey = videoExt.test(mediaUrl.split("?")[0]) ? "video" : "image";

  function platformMetadata(platform) {
    if (platform === "instagram") {
      if (assetKey === "video") {
        return "metadata: { instagram: { type: reel } }";
      }
      return "metadata: { instagram: { type: post, shouldShareToFeed: true } }";
    }
    if (platform === "facebook") {
      if (assetKey === "video") {
        return "metadata: { facebook: { type: reel } }";
      }
      return "metadata: { facebook: { type: post } }";
    }
    return null;
  }

  const targets = resolveTargets(content);
  if (targets.length === 0) {
    log("2/5 Prepare Buffer Posts", "ERROR no buffer targets", {
      contentId: content.contentId,
      channel: content.channel,
      platforms: content.platforms,
      bufferTargets: content.bufferTargets,
    });
    throw new Error(
      `No Buffer channel mapping for content ${content.contentId} (ช่องที่ลง: ${content.channel || "ไม่ระบุ"}). ตั้งค่า BUFFER_CHANNEL_MAP ใน .env`
    );
  }

  log("2/5 Prepare Buffer Posts", "resolved targets", {
    contentId: content.contentId,
    assetKey,
    mediaUrl,
    targetCount: targets.length,
    targets: targets.map(({ platform, bufferChannelId }) => ({
      platform,
      bufferChannelId,
    })),
  });

  for (const { platform, bufferChannelId: channelId } of targets) {
    const metadataLine = platformMetadata(platform);
    const metadataFragment = metadataLine ? `\n    ${metadataLine}` : "";

    const query = `mutation CreatePost {
  createPost(input: {
    channelId: ${JSON.stringify(channelId)}
    text: ${JSON.stringify(text)}
    schedulingType: automatic
    mode: shareNow
    assets: [{ ${assetKey}: { url: ${JSON.stringify(mediaUrl)} } }]${metadataFragment}
  }) {
    ... on PostActionSuccess {
      post { id }
    }
    ... on MutationError {
      message
    }
  }
}`;

    log("2/5 Prepare Buffer Posts", "building Buffer mutation", {
      contentId: content.contentId,
      platform,
      channelId,
      assetKey,
      metadataLine: metadataLine ?? "(none)",
      captionPreview: text.slice(0, 120),
      mediaUrl,
      graphqlQuery: query,
    });

    const bufferApiKey = $env.BUFFER_API_KEY;
    if (!bufferApiKey) {
      log("2/5 Prepare Buffer Posts", "ERROR BUFFER_API_KEY missing", {
        contentId: content.contentId,
      });
      throw new Error(
        "BUFFER_API_KEY is missing in n8n environment. Check .env and restart n8n."
      );
    }

    results.push({
      json: {
        contentId: content.id,
        contentCode: content.contentId,
        contentChannel: content.channel,
        platform,
        channelId,
        mediaUrl,
        caption: text,
        graphqlQuery: query,
        bufferBody: JSON.stringify({ query }),
        bufferAuth: `Bearer ${bufferApiKey}`,
      },
    });
  }
}

if (results.length === 0) {
  log("2/5 Prepare Buffer Posts", "ERROR no results", {});
  throw new Error(
    "No supported Buffer platforms. Check BUFFER_CHANNEL_MAP or BUFFER_*_CHANNEL_ID env vars."
  );
}

log("2/5 Prepare Buffer Posts", "done", {
  contentId: results[0]?.json?.contentCode,
  itemCount: results.length,
});

return results;

// n8n Code node — Run Once for All Items

function log(step, message, data) {
  const suffix =
    data === undefined ? "" : ` ${JSON.stringify(data, null, 2)}`;
  console.log(`[content-approved] ${step} | ${message}${suffix}`);
}

function extractHttpError(error) {
  const status = error.statusCode ?? error.httpCode ?? "?";
  const responseBody =
    error.response?.body ??
    error.response?.data ??
    error.body ??
    error.cause?.response?.body ??
    null;

  return {
    status,
    message:
      typeof error.message === "string"
        ? error.message
        : JSON.stringify(error).slice(0, 500),
    responseBody,
    errorKeys: Object.keys(error ?? {}),
  };
}

function isAlreadyOnBufferError(message) {
  if (!message) return false;
  const lower = message.toLowerCase();
  return (
    lower.includes("already got this") ||
    lower.includes("already scheduled or posted") ||
    lower.includes("not able to post the same thing twice")
  );
}

const results = [];

for (const item of $input.all()) {
  const {
    bufferAuth,
    bufferBody,
    contentId,
    contentCode,
    platform,
    channelId,
    mediaUrl,
    caption,
    graphqlQuery,
  } = item.json;

  log("3/5 Post to Buffer", "start", {
    contentCode,
    contentId,
    platform,
    channelId,
    mediaUrl,
    captionPreview: caption?.slice(0, 120) ?? null,
    graphqlQuery: graphqlQuery ?? JSON.parse(bufferBody || "{}").query ?? null,
    hasBufferAuth: Boolean(bufferAuth),
  });

  if (!bufferAuth || !bufferBody) {
    log("3/5 Post to Buffer", "ERROR missing buffer request fields", {
      contentCode,
      contentId,
      platform,
      hasBufferAuth: Boolean(bufferAuth),
      hasBufferBody: Boolean(bufferBody),
    });
    throw new Error(
      `Missing bufferAuth/bufferBody for content ${contentId}. Update Prepare Buffer Posts code.`
    );
  }

  const startedAt = Date.now();
  let data;
  try {
    data = await this.helpers.httpRequest({
      method: "POST",
      url: "https://api.buffer.com",
      headers: {
        "Content-Type": "application/json",
        Authorization: bufferAuth,
      },
      body: JSON.parse(bufferBody),
    });
  } catch (error) {
    const detail = extractHttpError(error);
    log("3/5 Post to Buffer", "ERROR HTTP request failed", {
      contentCode,
      contentId,
      platform,
      durationMs: Date.now() - startedAt,
      ...detail,
      graphqlQuery: graphqlQuery ?? JSON.parse(bufferBody).query,
    });
    throw new Error(
      `Buffer HTTP ${detail.status} (${platform}): ${detail.message}`
    );
  }

  log("3/5 Post to Buffer", "raw Buffer response", {
    contentCode,
    platform,
    durationMs: Date.now() - startedAt,
    response: data,
  });

  const bufferPostId = data?.data?.createPost?.post?.id;
  const errorMessage = data?.data?.createPost?.message;
  const typename = data?.data?.createPost?.__typename;

  log("3/5 Post to Buffer", "parsed Buffer response", {
    contentCode,
    platform,
    bufferPostId: bufferPostId ?? null,
    errorMessage: errorMessage ?? null,
    typename: typename ?? null,
  });

  if (!bufferPostId && errorMessage) {
    if (isAlreadyOnBufferError(errorMessage)) {
      log("3/5 Post to Buffer", "WARN duplicate on Buffer — treating as success", {
        contentCode,
        platform,
        errorMessage,
        note: "Post likely already queued from a prior attempt; will Mark Posted",
      });

      results.push({
        json: {
          contentId,
          contentCode,
          platform,
          channelId,
          mediaUrl,
          caption,
          bufferPostId: "already-on-buffer",
          duplicateSkipped: true,
          data,
        },
      });
      continue;
    }

    log("3/5 Post to Buffer", "ERROR Buffer mutation rejected", {
      contentCode,
      platform,
      errorMessage,
      fullResponse: data,
    });
    throw new Error(`Buffer mutation error (${platform}): ${errorMessage}`);
  }

  if (!bufferPostId) {
    log("3/5 Post to Buffer", "ERROR Buffer returned no post id", {
      contentCode,
      platform,
      fullResponse: data,
    });
    throw new Error(
      `Buffer returned no post id for ${contentCode} (${platform}). Response: ${JSON.stringify(data).slice(0, 500)}`
    );
  }

  log("3/5 Post to Buffer", "success", {
    contentCode,
    platform,
    bufferPostId,
    durationMs: Date.now() - startedAt,
  });

  results.push({
    json: {
      contentId,
      contentCode,
      platform,
      channelId,
      mediaUrl,
      caption,
      bufferPostId,
      data,
    },
  });
}

return results;

// n8n Code node — Run Once for All Items

function log(step, message, data) {
  const suffix =
    data === undefined ? "" : ` ${JSON.stringify(data, null, 2)}`;
  console.log(`[content-approved] ${step} | ${message}${suffix}`);
}

function extractHttpError(error) {
  const status = error.statusCode ?? error.httpCode ?? "?";
  const responseBody =
    error.response?.body ??
    error.response?.data ??
    error.body ??
    error.cause?.response?.body ??
    null;

  return {
    status,
    message:
      typeof error.message === "string"
        ? error.message
        : JSON.stringify(error).slice(0, 500),
    responseBody,
    errorKeys: Object.keys(error ?? {}),
  };
}

const results = [];

for (const item of $input.all()) {
  const { contentId, contentCode, platform, bufferPostId } = item.json;

  const apiKey = $env.N8N_API_KEY;
  const appUrl = ($env.APP_PUBLIC_URL || "http://localhost:3000").replace(
    /\/$/,
    ""
  );
  const url = `${appUrl}/api/content/${contentId}`;
  const requestBody = { status: "posted" };

  log("4/5 Mark Posted", "start PATCH app", {
    contentCode,
    contentId,
    platform,
    bufferPostId,
    url,
    requestBody,
    hasApiKey: Boolean(apiKey),
    note: "If this fails, content stays posting even though Buffer may have posted",
  });

  if (!apiKey) {
    throw new Error("N8N_API_KEY is missing in n8n environment.");
  }

  const startedAt = Date.now();

  try {
    const response = await this.helpers.httpRequest({
      method: "PATCH",
      url,
      headers: {
        "Content-Type": "application/json",
        "x-api-key": apiKey,
      },
      body: requestBody,
    });

    log("4/5 Mark Posted", "SUCCESS — flow complete", {
      contentCode,
      contentId,
      platform,
      bufferPostId,
      durationMs: Date.now() - startedAt,
      response,
      newStatus: response?.status ?? "posted",
    });

    results.push({
      json: {
        ...item.json,
        markPostedResponse: response,
      },
    });
  } catch (error) {
    const detail = extractHttpError(error);

    log("4/5 Mark Posted", "ERROR PATCH failed", {
      contentCode,
      contentId,
      platform,
      bufferPostId,
      durationMs: Date.now() - startedAt,
      ...detail,
      note: "Content likely still shows posting in app UI",
    });

    const bodyHint =
      detail.responseBody === null || detail.responseBody === undefined
        ? ""
        : ` body=${typeof detail.responseBody === "string" ? detail.responseBody : JSON.stringify(detail.responseBody)}`;

    throw new Error(
      `Mark Posted HTTP ${detail.status}: ${detail.message}${bodyHint}`
    );
  }
}

return results;

